  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Codeine, the closest structural analogue, showed about 90% systemic availability after oral administration in healthy volunteers, strongly supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Absolute oral bioavailability of codeine in healthy volunteers was 42–71%, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Morphine, a closely related morphinan, had an absolute oral bioavailability of 32% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Ethylmorphine, another close codeine analogue, had a median minimum oral availability of 0.74 (range 0.54–0.92), supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Noscapine, a related opium alkaloid, had an absolute oral bioavailability of 30% (range 16–58%), supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Pethidine, an opioid with an N-methyl piperidine motif, had an absolute bioavailability of 0.63 in healthy volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Cepharanthine had a low absolute oral bioavailability of 6–9% in humans, but its large bisbenzylisoquinoline structure is far less transferable to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C42"],
      "claim": "Morphine-6-glucuronide has poor oral bioavailability, but as a polar glucuronide conjugate it is not representative of the query's lipophilic morphinan scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high (F ≥ 20%) because the query is a codeine-like morphinan alkaloid; the closest analogues (codeine, ethylmorphine, morphine, noscapine, pethidine) have measured oral bioavailability mostly 30–90%, well above the threshold. The few low-bioavailability analogues are structurally distant and do not override the strong supportive evidence.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the exact query molecule.",
    "The fasted-state condition is not explicitly matched in most source records.",
    "Some records report relative or systemic availability rather than absolute oral bioavailability.",
    "Stereochemical or regiochemical differences between the query and codeine could alter first-pass metabolism."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

